function [xrho,xia,xtt,xtb,xtc,xtd,xtq,xte,xtD,xdeltat,xdeltab,xnhustart,xnhustarb,xDmax] = timescale_dke_1yp(tokamak,D,E,nr)% %Time scale calculations for checking the validity of the assumptions used in the Drift Kinetic equation solver% %	Input: %		- tokamak: tokamak name [1,p] (see ptok_dke_1yp.m file)%		- D: normalized quasilinear diffusion coefficient [1,1]%		- E: normalized electric field [1,1]%		- nr: number of radial points [1,1]%%	Output: %  		- xrho: normalized plasma minor radius [1,n]%		- xtt: transit time (s) [1,n]%		- xtb: bounce time (s) [1,n]%		- xtc: collision time for passing electrons (s) [1,n]%		- xtd: detrapping time for trapped electrons (s) [1,n]%		- xtq: quasilinear diffusion time (s) [1,n]%		- xte: constant electric field acceleration time (s) [1,n]%		- xtD: Drift time (s) [1,n]%		- xdeltat: Drift parameter for passing electrons [1,n]%		- xdeltab: Drift parameter for bouncing electrons [1,n]%		- xdnhustart: Collision parameter for passing electrons [1,n]%		- xnhustarb: Collision parameter for bouncing electrons [1,n]%		- sDmax: maximum quasilinear diffusion coefficient [1,n]%%	Warning: None%	  %Last Update: 19/11/2002%%by Y.Peysson CEA-DRFC 19/11/2002 <yves.peysson@cea.fr>%if nargin < 1,    error('Wrong number of input arguments in timescale_dke_1yp')elseif nargin == 1,    D = 1 ;    E = 0;    nr = 100;elseif nargin == 2,    E = 0;	nr = 100;elseif nargin == 3,    nr = 100;end%warning off%xrho = linspace(0,1,nr);%qe = 1.60217733e-19;%Electron charge (C)me = 9.1093897e-31;%Electron rest mass (Kg)e0 = 8.854187818e-12;%Free space permeability (F/m)re = 2.82e-15;%Classical electron radius (m)mc2 = 510.99905;%Electron energy rest mass (keV)clum = 299792458;%Speed of light (m/s)%[ap,Rp,Ip,Bt,Ncoils,Zi,mi,fi,BeLi,qmin,eq,Te0,Tea,eTe,eTe,ne0,nea,ene,ene,Ti0,Tia,eTi,Zeff0,Zeffa,eZeff] = ptok_dke_1yp(tokamak);%See ptok_dke_1yp.m file for changing global tokamak parameters%%%Local plasma parameters%xTe = (Te0 - Tea)*(1 - xrho.^2).^eTe + Tea;%Electron temperature (keV)xne = (ne0 - nea)*(1 - xrho.^2).^ene + nea;%Electron density (m-3)xTi = (Ti0 - Tia)*(1 - xrho.^2).^eTi + Tia;%Dominant ion and impurity temperatures (usually, Ti = Te/2) (keV)xZeff = (Zeff0 - Zeffa)*(1 - xrho.^2).^eZeff + Zeffa;%Effective charge (a.u.)%%Local safety factor value%qmax = ap*ap*Bt/Rp/Ip/0.2;%Ampere's theorem at the plasma edge (circular plasma cross-section)xq = (qmax - qmin)*xrho.^eq + qmin;%%Ion density calculation (m-3)   ****** partially implemented *******%if (length(Zi) == 1),    xni = xne/Zi;elseif (length(Zi) == 2) & (max(max(Zi)) > 1),%   [ngaz,nimp] = lowz_dke_yp(ne,Te,Zeff,max(max(Zi)),min(min(Zi)));%One light impurity fully stripped model%   ni = [ngaz,nimp];elseif (length(Zi) <= 3) & (max(max(Zi)) == 1),%   if sum(fi) > 1,%       error('Wrong fraction of hydrogen isotops');%   else%       ni = fi*ne;%   endelse%   info_dke_yp(2,'Use an impurity transport or equilibrium model');   return;end%xTen = xTe/mc2;xbetath = sqrt(xTen);%Normalized pth_ref/mc as prescribed by Karney%xlnc = 15.2 - 0.5*log(xne/1e20)+log(xTe);%Reference Coulomb logarithm (in "Tokamaks" by Wesson)xnhu = qe^4*xne.*xlnc./(4*pi*e0^2*me^2*(clum*xbetath).^3);%Reference electron collision frequency (s-1)%xia = xrho.*ap/Rp;xBt = Bt./(1 + xia);xrlarmor = 1.07e-4*sqrt(xTe)./xBt;%xvth = xbetath*clum;xtt = 2*pi*xq*Rp./xvth;xtb = sqrt(2)*xq*Rp./xvth./sqrt(xia);%From Wesson "tokamaks" textbook, p.78-79xtc = 1./xnhu;xtd = 2*xtc.*xia;%From Wesson "tokamaks" textbook, p.78-79xtq = xtc/D;xte = xtc/E;xtD = xtt.*ap.*xrho./xrlarmor;%figure(1);semilogy(xrho,xtt,'r-',xrho,xtb,'r--',xrho,xtc,'b-',xrho,xtd,'b--',xrho,xtq,'g-.',xrho,xte,'c-.',xrho,xtD,'x')set(gca,'xlim',[0,1])legend('Transit','Bounce','Collision','Detrapping','Quasilinear','E-field','Drift'); zoom on;grid on;xlabel('r/a');ylabel('Time scale (s)');title(tokamak);%xdeltat = xtt./xtD;xdeltab = xtb./xtD;xnhueff = 1./xtd;xnhustarb = xnhueff.*xtb;xnhustart =  xnhu.*xtt;figure(2);semilogy(xrho,xdeltat,'r-',xrho,xdeltab,'r--',xrho,xnhustart,'b-',xrho,xnhustarb,'b--')set(gca,'xlim',[0,1])legend('delta transit','delta bounce','nhu* transit','nhu* bounce'); zoom on;grid on;xlabel('r/a');ylabel('Collision and drift parameters');title(tokamak);%xDmax = xtc./xtb;figure(3);semilogy(xrho,xDmax,'r-',xrho,D*ones(size(xrho)),'b-')set(gca,'xlim',[0,1]) legend('Dql(max.)','Dql(ref)'); zoom on;grid on;xlabel('r/a');ylabel('Dql');title(tokamak);%figure(4);subplot(321),plot(xrho,xTe,'-',xrho,xTi,'--')set(gca,'xlim',[0,1]) legend('Te','Ti'); zoom on;grid on;xlabel('r/a');ylabel('Te (keV)');title(tokamak);subplot(322),plot(xrho,xne/1e20)set(gca,'xlim',[0,1]) zoom on;grid on;xlabel('r/a');ylabel('ne (10+20 m-3)');title(tokamak);subplot(323),plot(xrho,xq)set(gca,'xlim',[0,1]) zoom on;grid on;xlabel('r/a');ylabel('Safety factor');title(tokamak);subplot(324),plot(xrho,xBt)set(gca,'xlim',[0,1]) zoom on;grid on;xlabel('r/a');ylabel('Magnetic field (T)');title(tokamak);subplot(325),plot(xrho,xia)set(gca,'xlim',[0,1]) zoom on;grid on;xlabel('r/a');ylabel('Inverse aspect ratio');title(tokamak);